// === Tab: mySketch.js ===



import { mountFlex } from "https://cdn.jsdelivr.net/npm/p5.flex@0.1.1/src/p5.flex.min.mjs"
/* [Inlined Multi-Tab] shader.js */

mountFlex(p5)

new p5((p) => {
	let theShader
	let Buffer
	let Canvas
	let img0, img1, img2
	let [resW, resH] = [1024, 576]
	let [deltaX, deltaY] = [0, 0]

	p.preload = () => {
		// get images from https://github.com/ZRNOF/.ink
		img0 = p.loadImage(get_image_url("Rain_Window_01.jpg"))
		img1 = p.loadImage(get_image_url("Tunnel_01.jpg"))
		img2 = p.loadImage(get_image_url("The_Dome_of_Light_02.jpg"))
	}

	p.setup = () => {
		if (p.windowWidth < p.windowHeight) [resW, resH] = [resH, resW]
		p.createCanvas(resW, resH, p.WEBGL)
		p.flex({ container: { padding: "20px" }, canvas: { fit: p.SCALE_DOWN } })
		p.pixelDensity(1)
		Buffer = p.createFramebuffer({ format: p.FLOAT })
		theShader = p.createShader(vert, frag)
		p.noStroke()
		p.imageMode(p.CENTER)
		p.background(51)
	}

	p.draw = () => {
		deltaX += p.map(p.mouseX, 0, p.width, 0.005, -0.005)
		deltaY += p.map(p.mouseY, 0, p.height, 0.005, -0.005)
		Buffer.draw(() => {
			p.shader(theShader)
			theShader.setUniform("iResolution", [p.width, p.height])
			theShader.setUniform("iPixelDensity", p.pixelDensity())
			theShader.setUniform("iCanvas", Canvas)
			theShader.setUniform("iImage0", img0)
			theShader.setUniform("iImage1", img1)
			theShader.setUniform("iImage2", img2)
			theShader.setUniform("iMouse", [p.mouseX, p.mouseY])
			theShader.setUniform("iTime", p.frameCount)
			theShader.setUniform("iDelta", [deltaX, deltaY])
			p.rect(0, 0, p.width, p.height)
		})

		p.image(Buffer, 0, 0)
		Border("#FFFFFF", 10)

		ClickStop()
	}

	const Border = (color, weight) => {
		p.push()
		p.noFill()
		p.stroke(color)
		p.strokeWeight(weight * 2)
		p.rectMode(p.CENTER)
		p.rect(0, 0, p.width, p.height)
		p.pop()
	}

	let CLICK = false
	p.mouseClicked = () => {
		CLICK = !CLICK
		if (!CLICK) p.loop()
	}
	const ClickStop = () => {
		if (CLICK) p.noLoop()
	}
})

// see https://github.com/ZRNOF/.ink
function get_image_url(filename) {
	let root = "https://raw.githubusercontent.com/ZRNOF/.ink/main/Package/"
	return root + filename
}



// === Tab: shader.js ===


import * as Shox from "https://cdn.jsdelivr.net/npm/shox@1.0.0/src/Shox.js"

const frag = `#version 300 es
	precision mediump float;

	uniform vec2 iResolution;
	uniform float iPixelDensity;
	uniform sampler2D iCanvas;
	uniform sampler2D iImage0;
	uniform sampler2D iImage1;
	uniform sampler2D iImage2;
	uniform vec2 iMouse;
	uniform float iTime;
	uniform vec2 iDelta;

	${Shox.displace}
	${Shox.noiseMath}
	${Shox.snoise3D}
	${Shox.snoise3DImage}
	${Shox.extend}

	vec4 noiseImage(vec2 uv, float scal, float gain, float ofst, vec3 move) {
		vec4 dimg = 1.0*snoise3DImage((uv-vec2(421., 132))*1., scal, gain, ofst, move);
		dimg +=    0.25*snoise3DImage((uv-vec2(834., 724))*4., scal, gain, ofst, move);
		dimg +=  0.0625*snoise3DImage((uv-vec2(387., 99))*16., scal, gain, ofst, move);
		return dimg/1.3125;
	}

	in vec2 vTexCoord;
	out vec4 fragColor;
	void main() {
		vec2 uv = vTexCoord;
		vec2 mouse = iMouse.xy/iResolution.xy;

		vec3 trans = vec3(iDelta.x, iDelta.y, iTime*0.002);
		vec4 dimg = noiseImage(uv, 1., 1., .5, trans);

		vec2 duv = displace(uv, dimg.rb, .5, 3.);
		duv = mirror(duv, 1.);

		vec4 img0 = texture(iImage0, duv);
		vec4 img1 = texture(iImage1, duv);
		vec4 img2 = texture(iImage2, duv);

		// fade slideshow
		vec4 col;
		float time = iTime*.005;
		float it = floor(time);
		float grad = .5+.5*sin((fract(time)-.5)*3.14159);
		if (mod(it, 3.) == 0.) { col = mix(img0, img1, grad); }
		if (mod(it, 3.) == 1.) { col = mix(img1, img2, grad); }
		if (mod(it, 3.) == 2.) { col = mix(img2, img0, grad); }

		fragColor = col;
	}
`

const vert = `#version 300 es

	in vec3 aPosition;
	in vec2 aTexCoord;

	out vec2 vTexCoord;

	void main() {
		vTexCoord = aTexCoord;
		gl_Position = vec4(aPosition.xy*2.-1., aPosition.z, 1.);
	}
`

